import json

import pytest

from epicstaff_plugin.cli.main import main
from epicstaff_plugin.package_layout import read_package_file
from epicstaff_plugin.problems import PackageProblemsError
from epicstaff_plugin.requirements_lock import backend_lock_problems, lock_line, parse_requirements_lock
from package_helpers import sample_files, write_archive

HASH_A = "a" * 64
HASH_B = "b" * 64
HASH_C = "c" * 64

# What `uv pip compile --universal --generate-hashes` writes: continuation lines, comments,
# markers.
UV_LOCK = f"""\
# This file was autogenerated by uv via the following command:
#    uv pip compile backend/requirements.in --universal --python-version 3.13 --generate-hashes
colorama==0.4.6 ; sys_platform == 'win32' \\
    --hash=sha256:{HASH_A}
    # via click
epicstaff-plugin==0.1.0 --hash=sha256:{HASH_B}
Uvicorn[standard]==0.52.3 \\
    --hash=sha256:{HASH_B} \\
    --hash=sha256:{HASH_C}
    # via -r backend/requirements.in
""".encode()

BACKEND_MANIFEST_CHANGES = {"backend": {"python": "3.13", "entrypoint": "weather_plugin.app:app"}}


def test_a_lock_written_by_uv_is_read():
    lock = parse_requirements_lock(UV_LOCK)

    assert [(pin.name, str(pin.version), pin.sha256, pin.line_number) for pin in lock.requirements] == [
        ("colorama", "0.4.6", (HASH_A,), 3),
        ("epicstaff-plugin", "0.1.0", (HASH_B,), 6),
        ("uvicorn", "0.52.3", (HASH_B, HASH_C), 7),
    ]
    colorama = lock.pins("Colorama")[0]
    assert not colorama.applies_to({"sys_platform": "linux"})
    assert colorama.applies_to({"sys_platform": "win32"})


@pytest.mark.parametrize(
    ("line", "message"),
    [
        ("uvicorn==0.52.3", "uvicorn has no --hash=sha256: digest"),
        (f"uvicorn>=0.52 --hash=sha256:{HASH_A}", "must be pinned to one exact version"),
        (f"uvicorn==0.52.* --hash=sha256:{HASH_A}", "must be pinned to one exact version"),
        (f"uvicorn==0.52.3 --hash=sha512:{HASH_A}", "the only option is --hash=sha256"),
        (f"uvicorn==0.52.3 --hash=sha256:{HASH_A[:-1]}", "the only option is --hash=sha256"),
        ("--index-url https://example.com/simple", "the lock may only pin requirements"),
        ("-e ./local", "the lock may only pin requirements"),
        ("-r other.txt", "the lock may only pin requirements"),
        (f"uvicorn @ https://example.com/uvicorn.whl --hash=sha256:{HASH_A}", "is a URL or path"),
        (f"not a requirement --hash=sha256:{HASH_A}", "is not a requirement"),
    ],
)
def test_a_lock_line_that_is_not_an_exact_hashed_pin_is_refused(line, message):
    with pytest.raises(PackageProblemsError) as raised:
        parse_requirements_lock(f"# header\n{line}\n".encode())

    (problem,) = raised.value.problems
    assert problem.loc == "package.backend/requirements.lock"
    assert problem.message.startswith("line 2: ")
    assert message in problem.message


def test_a_lock_that_is_not_utf8_is_refused():
    with pytest.raises(PackageProblemsError, match="is not UTF-8"):
        parse_requirements_lock(b"\xff\xfe")


def test_lock_line_pins_a_wheel_by_its_normalized_name():
    assert lock_line("EpicStaff_Plugin", "0.1.0", HASH_A) == f"epicstaff-plugin==0.1.0 --hash=sha256:{HASH_A}"


def test_a_backend_lock_must_pin_uvicorn_and_the_sdk():
    lock = f"fastapi==0.141.1 --hash=sha256:{HASH_A}\n".encode()

    messages = [problem.message for problem in backend_lock_problems(lock, [])]

    assert messages == [
        "does not pin epicstaff-plugin, which every plugin backend needs",
        "does not pin uvicorn, which every plugin backend needs",
    ]


def test_the_sdk_pin_may_be_left_to_pack_for_a_source_directory():
    lock = f"uvicorn==0.52.3 --hash=sha256:{HASH_A}\n".encode()

    assert backend_lock_problems(lock, [], require_sdk_pin=False) == []


def test_every_wheel_must_be_pinned_by_the_lock():
    wheels = [
        "backend/wheels/uvicorn-0.52.3-py3-none-any.whl",
        "backend/wheels/uvicorn-0.52.2-py3-none-any.whl",
        "backend/wheels/h11-0.16.0-py3-none-any.whl",
        "backend/wheels/not-a-wheel.whl",
    ]

    problems = {problem.loc: problem.message for problem in backend_lock_problems(UV_LOCK, wheels)}

    assert problems == {
        "package.backend/wheels/uvicorn-0.52.2-py3-none-any.whl": "is uvicorn 0.52.2, which backend/requirements.lock does not pin",
        "package.backend/wheels/h11-0.16.0-py3-none-any.whl": "is h11 0.16.0, which backend/requirements.lock does not pin",
        "package.backend/wheels/not-a-wheel.whl": "is not a valid wheel file name",
    }


def _backend_package(tmp_path, manifest_document, lock, wheels=None):
    manifest = {**manifest_document, **BACKEND_MANIFEST_CHANGES}
    files = {
        **sample_files(manifest),
        "backend/src/weather_plugin/__init__.py": b"",
        "backend/src/weather_plugin/app.py": b"app = None\n",
        "backend/requirements.lock": lock,
        **(wheels or {}),
    }
    return write_archive(tmp_path / "weather.esplugin", files)


def test_an_uploaded_backend_package_passes_with_a_good_lock(tmp_path, manifest_document):
    package = _backend_package(
        tmp_path, manifest_document, UV_LOCK, {"backend/wheels/uvicorn-0.52.3-py3-none-any.whl": b"wheel"}
    )

    assert read_package_file(package).manifest.backend.entrypoint == "weather_plugin.app:app"


def test_an_uploaded_backend_package_is_checked_against_its_lock(tmp_path, manifest_document):
    lock = f"uvicorn==0.52.3\nepicstaff-plugin==0.1.0 --hash=sha256:{HASH_A}\n".encode()
    package = _backend_package(
        tmp_path, manifest_document, lock, {"backend/wheels/fastapi-0.141.1-py3-none-any.whl": b"wheel"}
    )

    with pytest.raises(PackageProblemsError) as raised:
        read_package_file(package)

    assert {problem.loc: problem.message for problem in raised.value.problems} == {
        "package.backend/requirements.lock": "line 1: uvicorn has no --hash=sha256: digest",
    }


def test_a_backend_package_whose_lock_misses_the_sdk_is_refused(tmp_path, manifest_document):
    lock = f"uvicorn==0.52.3 --hash=sha256:{HASH_A}\n".encode()

    with pytest.raises(PackageProblemsError, match="does not pin epicstaff-plugin"):
        read_package_file(_backend_package(tmp_path, manifest_document, lock))


def _backend_source(plugin_source, lock):
    source, spa = plugin_source
    manifest = json.loads((source / "manifest.json").read_text())
    (source / "manifest.json").write_text(json.dumps({**manifest, **BACKEND_MANIFEST_CHANGES}))
    (source / "backend" / "src" / "weather_plugin").mkdir(parents=True)
    (source / "backend" / "src" / "weather_plugin" / "app.py").write_text("app = None\n")
    (source / "backend" / "requirements.lock").write_bytes(lock)
    return source, spa


def test_validating_a_source_without_the_sdk_pin_passes_with_a_note(plugin_source, capsys):
    source, spa = _backend_source(plugin_source, f"uvicorn==0.52.3 --hash=sha256:{HASH_A}\n".encode())

    assert main(["validate", str(source), "--spa-dir", str(spa)]) == 0
    assert (
        "note: backend/requirements.lock does not pin epicstaff-plugin; pack with --local-wheel"
        in capsys.readouterr().out
    )


def test_validating_a_source_with_a_bad_lock_fails(plugin_source, capsys):
    source, spa = _backend_source(plugin_source, b"uvicorn>=0.52\n")

    assert main(["validate", str(source), "--spa-dir", str(spa)]) == 1
    assert "package.backend/requirements.lock: line 1: uvicorn must be pinned" in capsys.readouterr().out
